#!/usr/bin/env python3
"""Generate or freshness-check the operators batch scenario manifests.

The operators batch exercises the OLM layer of the operator checks. The
golden, hugepages and bundle-count scenarios install a real operator through
OLM from an in-cluster opm registry that serves a File-Based Catalog embedded
in a ConfigMap: their bundles carry no bundle image, so OLM builds the install
plan inline from the CSV and objects embedded in the catalog, and nothing but
the operator's pause image is ever pulled. deploy.sh points an address-based
CatalogSource at the registry Service's ClusterIP and applies the Subscription
only afterwards.

The bad-csvs scenario applies hand-written CSVs into a namespace without an
OperatorGroup instead: OLM reconciles those to the Failed phase without
running any install strategy.

See README.md in this directory for how to add a test to a batch.
"""

import argparse
import base64
import json
import re
import sys
from pathlib import Path


SCRIPT_DIR = Path(__file__).resolve().parent
ROOT = SCRIPT_DIR.parents[4]
OPM_IMAGE = "quay.io/operator-framework/opm:v1.74.0"
PAUSE_IMAGE = "registry.k8s.io/pause:3.10"
CRD_GROUP = "scenario-smoke.example.com"
HEADER = "# Generated by batches/operators/generate-manifests.py; do not edit by hand.\n"
# The bundle-count catalog is the only manifest that comes close; past the
# apiserver request limit kubectl apply would reject the object outright.
MAX_MANIFEST_BYTES = 900 * 1024


# ---------------------------------------------------------------------------
# Minimal YAML emitter (stdlib only)

PLAIN = re.compile(r"^[A-Za-z_/][A-Za-z0-9_./-]*$")
AMBIGUOUS = {"true", "false", "yes", "no", "on", "off", "null", "y", "n"}


class Literal(str):
    """A multi-line string emitted as a YAML literal block."""


def scalar(value):
    if isinstance(value, Literal):
        raise ValueError("literal blocks are only supported as mapping values")
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if PLAIN.match(value) and value.lower() not in AMBIGUOUS:
        return value
    return json.dumps(value)


def emit(value, indent=0):
    pad = " " * indent
    lines = []
    if isinstance(value, dict):
        if not value:
            return [pad + "{}"]
        for key, item in value.items():
            if isinstance(item, Literal):
                lines.append(f"{pad}{key}: |-")
                lines.extend(f"{pad}  {line}" if line else pad for line in item.splitlines())
            elif isinstance(item, (dict, list)) and item:
                lines.append(f"{pad}{key}:")
                lines.extend(emit(item, indent + 2))
            elif isinstance(item, dict):
                lines.append(f"{pad}{key}: {{}}")
            elif isinstance(item, list):
                lines.append(f"{pad}{key}: []")
            else:
                lines.append(f"{pad}{key}: {scalar(item)}")
    else:
        for item in value:
            if isinstance(item, dict) and item:
                nested = emit(item, indent + 2)
                lines.append(f"{pad}- {nested[0].lstrip()}")
                lines.extend(nested[1:])
            elif isinstance(item, list) and item:
                raise ValueError("nested lists are not supported")
            else:
                lines.append(f"{pad}- {scalar(item)}")
    return lines


def render(objects):
    body = []
    for obj in objects:
        body.append("---")
        body.extend(emit(obj))
    return HEADER + "\n".join(body) + "\n"


def render_fbc(docs):
    # The embedded catalog is one multi-document YAML string inside the
    # ConfigMap, so it must not carry this file's generated-by header.
    lines = []
    for doc in docs:
        lines.append("---")
        lines.extend(emit(doc))
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# CSV, CRD and File-Based Catalog builders

INSTALL_MODES_OWN = [
    {"type": "OwnNamespace", "supported": True},
    {"type": "SingleNamespace", "supported": False},
    {"type": "MultiNamespace", "supported": False},
    {"type": "AllNamespaces", "supported": False},
]

INSTALL_MODES_SINGLE = [
    {"type": "OwnNamespace", "supported": False},
    {"type": "SingleNamespace", "supported": True},
    {"type": "MultiNamespace", "supported": False},
    {"type": "AllNamespaces", "supported": False},
]


def operator_deployment(name, pod_label, resources=None, volume=None):
    # The deployment embedded in a CSV install strategy; OLM creates it in the
    # operator namespace with the CSV as its owner. The pod never does
    # anything - only its labels and resources are checked.
    container = {
        "name": "operator",
        "image": PAUSE_IMAGE,
        "imagePullPolicy": "IfNotPresent",
        "resources": resources or {"requests": {"cpu": "50m", "memory": "64Mi"}},
    }
    spec = {"containers": [container]}
    if volume is not None:
        container["volumeMounts"] = [{"name": volume["name"], "mountPath": "/hugepages"}]
        spec["volumes"] = [volume]
    return {
        "name": name,
        "spec": {
            "replicas": 1,
            "selector": {"matchLabels": {"app": name}},
            "template": {
                "metadata": {"labels": {"app": name, pod_label: "target"}},
                "spec": spec,
            },
        },
    }


def csv_object(name, version, deployment, install_modes, owned_crds=None, cluster_permissions=None, annotations=None, namespace=None):
    # Objects embedded in an FBC bundle must not set metadata.namespace (OLM
    # assigns it); only the hand-applied bad-csvs manifests set one.
    metadata = {"name": name}
    if namespace:
        metadata["namespace"] = namespace
    if annotations:
        metadata["annotations"] = annotations
    spec = {
        "displayName": name,
        "description": "Scenario smoke operator.",
        "version": version,
        "provider": {"name": "scenario-smoke"},
        "maintainers": [{"name": "scenario-smoke", "email": "no-reply@redhat.com"}],
        "links": [{"name": "scenario-smoke", "url": "https://example.com"}],
        "installModes": install_modes,
        "install": {"strategy": "deployment", "spec": {"deployments": [deployment]}},
    }
    if owned_crds is not None:
        # The CSV type's JSON tag is all lowercase. The FBC install path
        # tolerates the camelCase spelling (Go's json decoding is
        # case-insensitive), but kubectl's strict server-side field validation
        # rejects it, so hand-applied CSVs must use the exact tag.
        spec["customresourcedefinitions"] = {"owned": owned_crds}
    if cluster_permissions is not None:
        # Cluster-scoped RBAC lives inside the deployment install strategy:
        # certsuite reads csv.Spec.InstallStrategy.StrategySpec.ClusterPermissions.
        spec["install"]["spec"]["clusterPermissions"] = cluster_permissions
    return {
        "apiVersion": "operators.coreos.com/v1alpha1",
        "kind": "ClusterServiceVersion",
        "metadata": metadata,
        "spec": spec,
    }


def crd_object(plural, kind, version_name):
    # A structural schema is mandatory for served apiextensions/v1 versions.
    # crd-versioning validates the version name itself: "v0" is a valid label
    # for the apiserver but fails certsuite's version regex, which requires a
    # nonzero digit.
    return {
        "apiVersion": "apiextensions.k8s.io/v1",
        "kind": "CustomResourceDefinition",
        "metadata": {"name": f"{plural}.{CRD_GROUP}"},
        "spec": {
            "group": CRD_GROUP,
            "names": {"plural": plural, "singular": plural[:-1], "kind": kind, "listKind": f"{kind}List"},
            "scope": "Namespaced",
            "versions": [
                {
                    "name": version_name,
                    "served": True,
                    "storage": True,
                    "schema": {"openAPIV3Schema": {"type": "object", "properties": {"spec": {"type": "object"}}}},
                }
            ],
        },
    }


def crd_description(plural, kind, version_name):
    # The owned-CRD entry of a CSV spec; single-crd-owner reads these even
    # when the CRD itself is never created on the cluster.
    return {
        "name": f"{plural}.{CRD_GROUP}",
        "version": version_name,
        "kind": kind,
        "displayName": kind,
        "description": "Scenario smoke CRD.",
    }


def package_doc(package):
    return {"schema": "olm.package", "name": package, "defaultChannel": "stable"}


def channel_doc(package, entries):
    return {
        "schema": "olm.channel",
        "name": "stable",
        "package": package,
        "entries": entries,
    }


def chained_entries(names):
    # A channel graph needs exactly one head, and a name-only entry is its own
    # head: only the single-entry catalogs can get away with those. Chaining
    # every bundle with replaces leaves the last entry as the only head.
    entries = []
    previous = None
    for name in names:
        entry = {"name": name}
        if previous is not None:
            entry["replaces"] = previous
        previous = name
        entries.append(entry)
    return entries


def bundle_doc(name, package, version, objects, image=None):
    # An FBC bundle without an image: OLM builds its install plan inline from
    # the embedded objects instead of resolving a bundle image. The
    # bundle-count fillers do set an image but carry no objects, because
    # nothing ever resolves them - they only need to be counted.
    properties = [{"type": "olm.package", "value": {"packageName": package, "version": version}}]
    for obj in objects:
        data = base64.b64encode(json.dumps(obj).encode("utf-8")).decode("ascii")
        properties.append({"type": "olm.bundle.object", "value": {"data": data}})
    doc = {"schema": "olm.bundle", "name": name, "package": package, "properties": properties}
    if image is not None:
        doc["image"] = image
    return doc


# ---------------------------------------------------------------------------
# Cluster object builders

# Namespaces are not part of the manifests: deploy.sh creates them, so the
# same manifest files stay valid for any kubeconfig.


def fbc_config_map(namespace, name, docs):
    return {
        "apiVersion": "v1",
        "kind": "ConfigMap",
        "metadata": {"name": name, "namespace": namespace},
        "data": {"catalog.yaml": Literal(render_fbc(docs))},
    }


def opm_deployment(namespace, name, catalog_source, config_map):
    # Serves the FBC from the mounted ConfigMap on port 50051. The
    # olm.catalogSource label pairs the pod with its Service's selector, which
    # is how certsuite's bundle-count probe finds the registry that serves a
    # CatalogSource.
    return {
        "apiVersion": "apps/v1",
        "kind": "Deployment",
        "metadata": {"name": name, "namespace": namespace},
        "spec": {
            "replicas": 1,
            "selector": {"matchLabels": {"app": name}},
            "template": {
                "metadata": {"labels": {"app": name, "olm.catalogSource": catalog_source}},
                "spec": {
                    "containers": [
                        {
                            "name": "opm",
                            "image": OPM_IMAGE,
                            "imagePullPolicy": "IfNotPresent",
                            "command": ["/bin/opm"],
                            # No --cache-dir: opm enforces cache integrity when
                            # one is set and fatals on a fresh directory. It
                            # builds an ephemeral cache without the flag.
                            "args": ["serve", "/fbc"],
                            "ports": [{"containerPort": 50051}],
                            # A ConfigMap volume projects each key as a symlink
                            # into a ..data directory; opm's loader walks the
                            # mount root and fatals reading ..data as a file.
                            # subPath mounts the single key as a regular file,
                            # giving /fbc the plain one-file layout opm expects.
                            "volumeMounts": [
                                {
                                    "name": "fbc",
                                    "mountPath": "/fbc/catalog.yaml",
                                    "subPath": "catalog.yaml",
                                    "readOnly": True,
                                }
                            ],
                            # Without a probe the pod is Ready while merely
                            # Running, so the rollout wait reports success
                            # before opm has served (or after it has crashed).
                            # The TCP probe makes it mean "accepting gRPC
                            # connections".
                            "readinessProbe": {
                                "tcpSocket": {"port": 50051},
                                "initialDelaySeconds": 2,
                                "periodSeconds": 5,
                            },
                        }
                    ],
                    "volumes": [{"name": "fbc", "configMap": {"name": config_map}}],
                },
            },
        },
    }


def opm_service(namespace, name, catalog_source):
    return {
        "apiVersion": "v1",
        "kind": "Service",
        "metadata": {"name": name, "namespace": namespace},
        "spec": {
            "selector": {"olm.catalogSource": catalog_source},
            "ports": [{"port": 50051, "targetPort": 50051}],
        },
    }


def catalog_source(namespace, name):
    # Address-based CatalogSource: deploy.sh patches spec.address with the
    # registry Service's ClusterIP, so OLM runs no registry pod for it.
    return {
        "apiVersion": "operators.coreos.com/v1alpha1",
        "kind": "CatalogSource",
        "metadata": {"name": name, "namespace": namespace},
        "spec": {"sourceType": "grpc", "address": ""},
    }


def operator_group(namespace, name, target_namespaces=None):
    # An OperatorGroup that lists its own namespace targets just that
    # namespace (OwnNamespace mode); golden targets a separate tenant
    # namespace instead, which makes the install SingleNamespace. An empty
    # spec would select ALL namespaces, which OwnNamespace-only CSVs reject.
    spec = {"targetNamespaces": target_namespaces if target_namespaces is not None else [namespace]}
    return {
        "apiVersion": "operators.coreos.com/v1",
        "kind": "OperatorGroup",
        "metadata": {"name": name, "namespace": namespace},
        "spec": spec,
    }


def subscription(namespace, name, package, catalog_source):
    # A separate manifest applied by deploy.sh only after the CatalogSource
    # address patch, so the first resolution already finds the catalog.
    return {
        "apiVersion": "operators.coreos.com/v1alpha1",
        "kind": "Subscription",
        "metadata": {"name": name, "namespace": namespace},
        "spec": {
            "name": package,
            "channel": "stable",
            "source": catalog_source,
            "sourceNamespace": namespace,
        },
    }


# ---------------------------------------------------------------------------
# golden batch: one cleanly OLM-installed operator, all twelve tests pass


def golden_manifests():
    operator_ns = "operators-golden-smoke-ns"
    catalog_ns = "operators-golden-catalog-smoke-ns"
    tenant_ns = "operators-golden-tenant-smoke-ns"
    package = "scenario-smoke-golden-operator"
    csv_name = "scenario-smoke-golden-operator.v1.0.0"
    cs_name = "scenario-smoke-golden-cs"

    # The bundle embeds the CRD next to the CSV, so OLM creates it from the
    # install plan. The skipRange annotation and the missing
    # clusterPermissions feed olm-skip-range and install-status-no-privileges.
    crd = crd_object("goldencrds", "GoldenCrd", "v1")
    csv = csv_object(
        csv_name,
        "1.0.0",
        operator_deployment("scenario-smoke-golden", "scenario-operators-golden"),
        INSTALL_MODES_SINGLE,
        owned_crds=[crd_description("goldencrds", "GoldenCrd", "v1")],
        annotations={"olm.skipRange": ">=0.0.0 <1.0.0"},
    )
    catalog = [
        package_doc(package),
        channel_doc(package, [{"name": csv_name}]),
        bundle_doc(csv_name, package, "1.0.0", [csv, crd]),
    ]
    cluster = [
        fbc_config_map(catalog_ns, "scenario-smoke-golden-fbc", catalog),
        opm_deployment(catalog_ns, "scenario-smoke-golden-opm", cs_name, "scenario-smoke-golden-fbc"),
        opm_service(catalog_ns, "scenario-smoke-golden-opm", cs_name),
        catalog_source(operator_ns, cs_name),
        # OLM annotates the installed CSV with olm.targetNamespaces and copies
        # it into the tenant namespace, which is not a target namespace.
        operator_group(operator_ns, "scenario-smoke-golden-og", [tenant_ns]),
    ]
    return {
        "golden/manifests/olm-golden.yaml": cluster,
        "golden/manifests/subscription.yaml": [
            subscription(operator_ns, "scenario-smoke-golden-subscription", package, cs_name)
        ],
    }


# ---------------------------------------------------------------------------
# bad-csvs batch: hand-applied CSVs in a namespace without an OperatorGroup


def bad_csvs_manifests():
    namespace = "operators-bad-smoke-ns"

    # The namespace gets no OperatorGroup, so OLM reconciles these CSVs to
    # the Failed phase (CSVReasonNoOperatorGroup) without running their
    # install strategy, and keeps the hand-set olm.operatorNamespace
    # annotation that discovery requires.
    annotations = {"olm.operatorNamespace": namespace}

    # The SCC clusterPermissions rule fails install-status-no-privileges.
    bad_scc = csv_object(
        "scenario-smoke-bad-scc.v1.0.0",
        "1.0.0",
        operator_deployment("scenario-smoke-bad-scc", "scenario-operators-bad"),
        INSTALL_MODES_OWN,
        cluster_permissions=[
            {
                "serviceAccountName": "scenario-smoke-bad-scc",
                "rules": [
                    {
                        "apiGroups": ["security.openshift.io"],
                        "resources": ["securitycontextconstraints"],
                        "verbs": ["use"],
                    }
                ],
            }
        ],
        annotations=annotations,
        namespace=namespace,
    )

    # Two CSVs with the same base name and different versions fail
    # multiple-same-operators, and both owning the same CRD (which is never
    # created on the cluster) fails single-crd-owner.
    dup_crds = [crd_description("dupcrds", "DupCrd", "v1")]
    dup_operator = [
        csv_object(
            f"scenario-smoke-dup-operator.v{version}",
            version,
            operator_deployment(f"scenario-smoke-dup-operator-v{version}", "scenario-operators-bad"),
            INSTALL_MODES_OWN,
            owned_crds=dup_crds,
            annotations=annotations,
            namespace=namespace,
        )
        for version in ("1.0.0", "2.0.0")
    ]

    # The served version name "v0" fails crd-versioning.
    bad_crd = crd_object("badcrds", "BadCrd", "v0")

    return {
        "bad-csvs/manifests/bad-csvs.yaml": [bad_scc, *dup_operator, bad_crd],
    }


# ---------------------------------------------------------------------------
# hugepages batch: a real OLM install whose operator pod cannot schedule


def hugepages_manifests():
    operator_ns = "operators-hugepages-smoke-ns"
    catalog_ns = "operators-hugepages-catalog-smoke-ns"
    package = "scenario-smoke-hugepages-operator"
    csv_name = "scenario-smoke-hugepages-operator.v1.0.0"
    cs_name = "scenario-smoke-hugepages-cs"

    # The operator pod requests hugepages-2Mi, which the Kind workers do not
    # have, so it stays Pending; discovery still associates it with the CSV
    # through its owner chain. Hugepages are non-overcommitable, so the
    # apiserver rejects a request without a matching limit, and it requires a
    # cpu or memory request alongside any hugepages request.
    csv = csv_object(
        csv_name,
        "1.0.0",
        operator_deployment(
            "scenario-smoke-hugepages",
            "scenario-operators-hugepages",
            resources={
                "requests": {"hugepages-2Mi": "64Mi", "cpu": "50m"},
                "limits": {"hugepages-2Mi": "64Mi"},
            },
            volume={"name": "hugepages", "emptyDir": {"medium": "HugePages"}},
        ),
        INSTALL_MODES_OWN,
    )
    catalog = [
        package_doc(package),
        channel_doc(package, [{"name": csv_name}]),
        bundle_doc(csv_name, package, "1.0.0", [csv]),
    ]
    cluster = [
        fbc_config_map(catalog_ns, "scenario-smoke-hugepages-fbc", catalog),
        opm_deployment(catalog_ns, "scenario-smoke-hugepages-opm", cs_name, "scenario-smoke-hugepages-fbc"),
        opm_service(catalog_ns, "scenario-smoke-hugepages-opm", cs_name),
        catalog_source(operator_ns, cs_name),
        operator_group(operator_ns, "scenario-smoke-hugepages-og"),
    ]
    return {
        "hugepages/manifests/hugepages.yaml": cluster,
        "hugepages/manifests/subscription.yaml": [
            subscription(operator_ns, "scenario-smoke-hugepages-subscription", package, cs_name)
        ],
    }


# ---------------------------------------------------------------------------
# bundle-count batch: a catalog with more than 1000 bundles


def bundle_count_manifests():
    operator_ns = "operators-big-smoke-ns"
    catalog_ns = "operators-big-catalog-smoke-ns"
    package = "scenario-smoke-big-operator"
    csv_name = "scenario-smoke-big-operator.v1.0.0"
    cs_name = "scenario-smoke-big-cs"
    filler_package = "scenario-smoke-filler"
    filler_count = 1001

    csv = csv_object(
        csv_name,
        "1.0.0",
        operator_deployment("scenario-smoke-big", "scenario-operators-big"),
        INSTALL_MODES_OWN,
    )
    catalog = [
        package_doc(package),
        channel_doc(package, [{"name": csv_name}]),
        bundle_doc(csv_name, package, "1.0.0", [csv]),
        # 1001 filler bundles plus the operator bundle itself push the
        # catalog past the 1000-bundle limit that bundle-count enforces.
        package_doc(filler_package),
        channel_doc(
            filler_package,
            chained_entries([f"scenario-smoke-filler.v0.0.{n}" for n in range(1, filler_count + 1)]),
        ),
    ]
    for n in range(1, filler_count + 1):
        catalog.append(
            bundle_doc(
                f"scenario-smoke-filler.v0.0.{n}",
                filler_package,
                f"0.0.{n}",
                [],
                image=f"quay.io/scenario-smoke/filler:v0.0.{n}",
            )
        )
    cluster = [
        fbc_config_map(catalog_ns, "scenario-smoke-big-fbc", catalog),
        opm_deployment(catalog_ns, "scenario-smoke-big-opm", cs_name, "scenario-smoke-big-fbc"),
        opm_service(catalog_ns, "scenario-smoke-big-opm", cs_name),
        catalog_source(operator_ns, cs_name),
        operator_group(operator_ns, "scenario-smoke-big-og"),
    ]
    return {
        "bundle-count/manifests/big-catalog.yaml": cluster,
        "bundle-count/manifests/subscription.yaml": [
            subscription(operator_ns, "scenario-smoke-big-subscription", package, cs_name)
        ],
    }


def all_manifests():
    manifests = {}
    manifests.update(golden_manifests())
    manifests.update(bad_csvs_manifests())
    manifests.update(hugepages_manifests())
    manifests.update(bundle_count_manifests())

    rendered = {}
    for relative, objects in manifests.items():
        content = render(objects)
        size = len(content.encode("utf-8"))
        if size > MAX_MANIFEST_BYTES:
            raise ValueError(f"{relative} renders to {size} bytes, over the {MAX_MANIFEST_BYTES}-byte limit")
        rendered[relative] = content
    return rendered


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if a generated manifest is stale")
    args = parser.parse_args()

    stale = []
    for relative, content in all_manifests().items():
        path = SCRIPT_DIR / relative
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                stale.append(str(path.relative_to(ROOT)))
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        print(f"Wrote {path.relative_to(ROOT)}")

    if stale:
        print("Operators batch manifests are stale. Run python3 .github/actions/test-scenarios/batches/operators/generate-manifests.py:", file=sys.stderr)
        for path in stale:
            print(f"  {path}", file=sys.stderr)
        return 1
    if args.check:
        print("Operators batch manifests are up to date.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
